func (this *CoolBar) wM_SIZE_(wParam int64, lParam int64) *win32.LRESULT {
	if this.ignoreResize {
		var code int64 = this.impl.callWindowProc_(this.Handle, win32.OSWM_SIZE, wParam, lParam)
		if code == 0 {
			return win32.LRESULTZERO
		}
		return win32.NewLRESULT(code)
	}
	return this.Composite.wM_SIZE_(wParam, lParam)
}

func (this *CoolBar) wmNotifyChild_(hdr *win32.NMHDR, wParam int64, lParam int64) *win32.LRESULT {
	switch hdr.Code {
	case win32.OSRBN_BEGINDRAG:
		{
			var pos int32 = win32.OSGetMessagePos()
			var pt *win32.POINT = win32.NewPOINT()
			win32.OSPOINTSTOPOINT(pt, int64(pos))
			win32.OSScreenToClient(this.Handle, pt)
			var button int32
			if this.display.lastButton != 0 {
				button = this.display.lastButton
			} else {
				button = 1
			}
			if !this.SendDragEvent(button, pt.X, pt.Y) {
				return win32.LRESULTONE
			}
			break
		}
	case win32.OSRBN_CHILDSIZE:
		{
			var lprbcs *win32.NMREBARCHILDSIZE = win32.NewNMREBARCHILDSIZE()
			win32.OSMoveMemoryOverload63(lprbcs, lParam, win32.NMREBARCHILDSIZESizeof)
			if lprbcs.UBand != -1 {
				var item *CoolItem = this.items[lprbcs.WID]
				var control *Control = item.control
				if control != (nil) {
					var width int32 = lprbcs.RcChild_right - lprbcs.RcChild_left
					var height int32 = lprbcs.RcChild_bottom - lprbcs.RcChild_top
					control.SetBoundsInPixels(lprbcs.RcChild_left, lprbcs.RcChild_top, width, height)
				}
			}
			break
		}
	case win32.OSRBN_HEIGHTCHANGE:
		{
			if !this.ignoreResize {
				var size *Point = this.impl.getSizeInPixels_()
				var border int32 = this.impl.getBorderWidthInPixels_()
				var barHeight int32 = int32(win32.OSSendMessageOverload4(this.Handle, win32.OSRB_GETBARHEIGHT, int64(0), int64(0)))
				if (this.style & VERTICAL) != 0 {
					this.SetSizeInPixels(barHeight+2*border, size.Y)
				} else {
					this.SetSizeInPixels(size.X, barHeight+2*border)
				}
			}
			break
		}
	case win32.OSRBN_CHEVRONPUSHED:
		{
			var lpnm *win32.NMREBARCHEVRON = win32.NewNMREBARCHEVRON()
			win32.OSMoveMemoryOverload64(lpnm, lParam, win32.NMREBARCHEVRONSizeof)
			var item *CoolItem = this.items[lpnm.WID]
			if item != (nil) {
				var event *Event = NewEvent()
				event.Detail = ARROW
				var zoom int32 = this.impl.getAutoscalingZoom_()
				if (this.style & VERTICAL) != 0 {
					event.SetLocation(DPIUtilPixelToPoint(lpnm.Right, zoom), DPIUtilPixelToPoint(lpnm.Top, zoom))
				} else {
					event.SetLocation(DPIUtilPixelToPoint(lpnm.Left, zoom), DPIUtilPixelToPoint(lpnm.Bottom, zoom))
				}
				item.SendSelectionEventEventTypeEventSend(Selection, event, false)
			}
			break
		}
	case win32.OSNM_CUSTOMDRAW:
		{
			if this.impl.findBackgroundControl_() != (nil) || (this.style&FLAT) != 0 {
				var nmcd *win32.NMCUSTOMDRAW = win32.NewNMCUSTOMDRAW()
				win32.OSMoveMemoryOverload44(nmcd, lParam, win32.NMCUSTOMDRAWSizeof)
				switch nmcd.DwDrawStage {
				case win32.OSCDDS_PREERASE:
					return win32.NewLRESULT(int64(win32.OSCDRF_SKIPDEFAULT | win32.OSCDRF_NOTIFYPOSTERASE))
				case win32.OSCDDS_POSTERASE:
					this.DrawBackground(nmcd.Hdc)
					break
				}
			}
			break
		}
	}
	return this.Composite.wmNotifyChild_(hdr, wParam, lParam)
}

func (this *CoolBar) handleDPIChange_(event *Event, scalingFactor float32) {
	this.Composite.handleDPIChange_(event, scalingFactor)
	var sizes []*Point = this.GetItemSizesInPixels()
	var scaledSizes []*Point = make([]*Point, int32(len(sizes)))
	var prefSizes []*Point = make([]*Point, int32(len(sizes)))
	var minSizes []*Point = make([]*Point, int32(len(sizes)))
	var indices []int32 = this.GetWrapIndices()
	var itemOrder []int32 = this.GetItemOrder()
	var items []*CoolItem = this.GetItems()
	for index := int32(0); index < int32(len(sizes)); index++ {
		minSizes[index] = items[index].GetMinimumSizeInPixels()
		prefSizes[index] = items[index].GetPreferredSizeInPixels()
	}
	for index := int32(0); index < int32(len(sizes)); index++ {
		var item *CoolItem = items[index]
		var control *Control = item.control
		if control != (nil) && !control.IsDisposed() {
			control.NotifyListeners(ZoomChanged, event)
			item.SetControl(control)
		}
		var preferredControlSize *Point = item.GetControl().impl.computeSizeInPixels_(NewPoint(DEFAULT, DEFAULT), this.impl.computeBoundsZoom_(), true)
		var controlWidth int32 = preferredControlSize.X
		var controlHeight int32 = preferredControlSize.Y
		if (this.style & VERTICAL) != 0 {
			scaledSizes[index] = NewPoint(int32(math.Floor(float64(float32((sizes[index].X))*scalingFactor)+0.5)), int32(math.Max(float64(int32(math.Floor(float64(float32((sizes[index].Y))*scalingFactor)+0.5))), float64(0))))
			item.SetMinimumSizeInPixels(int32(math.Floor(float64(float32(minSizes[index].X)*scalingFactor)+0.5)), int32(math.Max(float64(int32(math.Floor(float64(float32((minSizes[index].Y))*scalingFactor)+0.5))), float64(controlWidth))))
			item.SetPreferredSizeInPixels(int32(math.Floor(float64(float32(prefSizes[index].X)*scalingFactor)+0.5)), int32(math.Max(float64(int32(math.Floor(float64(float32((prefSizes[index].Y))*scalingFactor)+0.5))), float64(controlWidth))))
		} else {
			scaledSizes[index] = NewPoint(int32(math.Floor(float64(float32((sizes[index].X))*scalingFactor)+0.5)), int32(math.Max(float64(int32(math.Floor(float64(float32((sizes[index].Y))*scalingFactor)+0.5))), float64(0))))
			item.SetMinimumSizeInPixels(int32(math.Floor(float64(float32(minSizes[index].X)*scalingFactor)+0.5)), controlHeight)
			item.SetPreferredSizeInPixels(int32(math.Floor(float64(float32(prefSizes[index].X)*scalingFactor)+0.5)), controlHeight)
		}
	}
	this.SetItemLayoutInPixels(itemOrder, indices, scaledSizes)
}

func CoolBarCheckStyle(style int32) int32 {
	style |= NO_FOCUS
	return style & ^(H_SCROLL | V_SCROLL)
}

func upcastCoolBarToControl(x *CoolBar) *Control {
	if x == nil {
		return nil
	}
	return &x.Control
}

func init() {
	func() {
		defer func() {
			if r := recover(); r != nil {
				fmt.Fprintln(os.Stderr, "gowt: deferred init CoolBar static{}:", r)
			}
		}()
		var lpWndClass *win32.WNDCLASS = win32.NewWNDCLASS()
		win32.OSGetClassInfo(int64(0), CoolBarReBarClass, lpWndClass)
		CoolBarReBarProc = lpWndClass.LpfnWndProc
	}()
}
